const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>(T[S.locale]&&T[S.locale][k])||T.ar[k]||k;
const L=o=>o[S.locale]||o.ar;
const fmtBytes=b=>!b?'0 B':b<1024?b+' B':b<1048576?(b/1024).toFixed(1)+' KB':(b/1048576).toFixed(2)+' MB';
function hearts(n){const e=['💖','🌸','✨','🎀','💫','🌷','💝','⭐'];for(let i=0;i<(n||12);i++){const s=document.createElement('span');s.className='heart';s.textContent=e[Math.floor(Math.random()*e.length)];s.style.left=(5+Math.random()*90)+'vw';s.style.fontSize=(16+Math.random()*20)+'px';s.style.animationDuration=(2.4+Math.random()*1.8)+'s';s.style.animationDelay=(Math.random()*.5)+'s';document.body.appendChild(s);setTimeout(()=>s.remove(),4800);}}
async function jget(r){const res=await fetch(API+r,{cache:'no-store'});const d=await res.json().catch(()=>({}));if(!res.ok){const e=new Error(d.message||d.error||'generic');e.code=d.error;throw e;}return d;}
async function jpost(r,b){const res=await fetch(API+r,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})});const d=await res.json().catch(()=>({}));if(!res.ok){const e=new Error(d.message||d.error||'generic');e.code=d.error;throw e;}return d;}
function chrome(){document.documentElement.lang=S.locale;document.documentElement.dir=S.locale==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=S.theme;try{localStorage.setItem('luna.locale',S.locale);localStorage.setItem('luna.theme',S.theme);}catch(e){}}
try{const l=localStorage.getItem('luna.locale');if(l&&T[l])S.locale=l;const th=localStorage.getItem('luna.theme');if(th)S.theme=th;}catch(e){}
async function runLoop(bookId,idxs,onTick){const q=[...idxs];let done=0,failed=0;const w=async()=>{while(q.length){const idx=q.shift();try{const r=await jpost('fetch&id='+bookId+'&idx='+idx);if(r.chapter&&r.chapter.status==='done')done++;else failed++;onTick(r.chapter||{idx,status:'failed'},{total:idxs.length,done,failed,current:idx});}catch(e){failed++;onTick({idx,status:'failed',error:'fetch-failed'},{total:idxs.length,done,failed,current:idx});}}};await Promise.all([w(),w(),w()]);return{done,failed};}
/* ---------- rendering ---------- */
function header(){return `<header class="top"><div class="in"><a class="brand" href="#/"><span class="moon">🌙</span><span><b class="gold">${esc(t('brand'))}</b><small>${esc(t('tagline'))}</small></span></a><div class="row"><div class="seg">${['ar','fr','en'].map(l=>`<button class="${S.locale===l?'on':''}" onclick="LC.locale('${l}')">${{ar:'🌸',fr:'🎀',en:'💫'}[l]} ${l.toUpperCase()}</button>`).join('')}</div><div class="seg">${[['girl','linear-gradient(120deg,#b79cf5,#7a2554,#d9b04c)'],['rose','linear-gradient(120deg,#ff7fa8,#c53a63,#e0a83f)'],['mint','linear-gradient(120deg,#7fd8c4,#2f8f7c,#d3b25a)']].map(x=>`<span class="sw ${S.theme===x[0]?'on':''}" style="background:${x[1]}" onclick="LC.theme('${x[0]}')"></span>`).join('')}</div></div></div></header>`;}
function importStatus(){const i=S.imp;if(i.phase==='idle')return'';const p=i.progress;const pct=p&&p.total?Math.round((p.done+p.failed)/p.total*100):(i.phase==='meta'?8:4);const label=i.phase==='meta'?'🎀 '+t('readingMeta'):i.phase==='chapters'?'💞 '+t('fetchingChapter')+' #'+(p?p.current:'')+' • '+(p?p.done+'/'+p.total:''):i.phase==='done'?'🎉 '+t('done'):'🥺 '+t('errorGeneric');return `<div class="card boing" style="padding:14px;margin-top:12px"><div class="row between"><b style="color:var(--plum);font-size:.9rem">${label}</b></div><div class="progress" style="margin:10px 0"><span style="width:${Math.max(pct,4)}%"></span></div>${i.book?`<div class="row">${i.book.hasCover?`<img src="${API}cover&id=${i.book.id}" alt="" style="width:48px;height:64px;object-fit:cover;border-radius:10px;box-shadow:0 8px 18px var(--glow)">`:'<span style="font-size:28px">🌸</span>'}<div><b style="color:var(--plum)">${esc(i.book.title)}</b><div class="muted">${esc(i.book.author||'—')} • ${i.chapters.length} ${t('chaptersFound')}</div></div></div>`:''}${i.error?`<p class="err">${esc(i.error)}</p>`:''}</div>`;}
function home(){const libs=S.books.length?`<div class="grid g3">${S.books.map(b=>{const pct=b.totalChapters?Math.round((b.doneChapters||0)/b.totalChapters*100):0;const st=b.totalChapters&&(b.doneChapters||0)>=b.totalChapters?['ok','✅ '+t('statusReady')]:(b.doneChapters||0)>0?['wait','💗 '+(b.doneChapters||0)+'/'+b.totalChapters]:b.failedChapters>0?['bad','💔 '+t('statusFailed')]:['wait','⏳ '+t('statusImporting')];return `<article class="card lib boing" style="padding:12px">${b.hasCover?`<a href="#/book/${b.id}"><img src="${API}cover&id=${b.id}" alt=""></a>`:`<a href="#/book/${b.id}" class="ph">🌷</a>`}<div style="min-width:0;flex:1;display:flex;flex-direction:column;gap:6px"><a href="#/book/${b.id}" style="text-decoration:none"><b style="display:block;color:var(--plum);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(b.title)}</b><span class="muted small">${esc(b.author||'—')}</span></a><span class="badge ${st[0]}" style="width:fit-content">${st[1]}</span><div class="progress thin"><span style="width:${Math.max(pct,3)}%"></span></div><div class="row" style="margin-top:auto"><a class="soft small" href="#/book/${b.id}">👀 ${t('preview')}</a><button class="soft small" onclick="LC.del(${b.id})">🗑️ ${t('delete')}</button></div></div></article>`;}).join('')}</div>`:`<p class="card muted" style="text-align:center">${t('libraryEmpty')}</p>`;
return `<main class="wrap">
<section class="card" style="padding:28px"><div class="deco"></div><span class="chip">💗 ${t('everySite')}</span><h1 class="gold">${esc(t('heroTitle'))}</h1><p class="muted" style="max-width:760px;line-height:1.9">${esc(t('heroSubtitle'))}</p><div class="row"><a class="btn" href="#import">🎀 ${t('pasteButton')}</a><span class="soft">📦 EPUB • PDF • HTML • TXT • MD • DOCX • FB2 • JSON</span></div></section>
<section class="card" id="import"><div class="deco"></div><div class="row between"><h2>${t('pasteLabel')}</h2><div><span class="chip">💗 ${t('everySite')}</span><span class="chip">Novlar</span><span class="chip">Uranus-Novel</span><span class="chip">Wattpad</span></div></div><div class="row" style="margin-top:10px"><input id="url" class="input" dir="ltr" spellcheck="false" placeholder="${esc(t('pastePlaceholder'))}" style="flex:1;min-width:240px" onkeydown="if(event.key==='Enter')LC.start()" ${S.imp.phase==='meta'||S.imp.phase==='chapters'?'disabled':''}/><button class="btn" id="go" onclick="LC.start()" ${S.imp.phase==='meta'||S.imp.phase==='chapters'?'disabled':''}>${S.imp.phase==='meta'||S.imp.phase==='chapters'?t('importing'):t('pasteButton')}</button></div><p class="muted small">🔒 ${t('pasteHint')}</p><div id="importStatus">${importStatus()}</div></section>
<section class="grid g3">${FEATURES.map(f=>`<article class="card"><span style="font-size:26px">${f[0]}</span><h3>${esc(L(f[1]))}</h3><p class="muted small" style="margin:0">${esc(L(f[2]))}</p></article>`).join('')}</section>
<section><h2>📚 ${t('library')}</h2>${libs}</section>
<section class="card"><h2>✨ ${t('howTo')}</h2><ol class="steps">${[1,2,3,4].map(n=>`<li><i>${n}</i>${esc(t('step'+n))}</li>`).join('')}</ol></section>
<footer class="card f"><b style="color:var(--plum)">🌙 ${esc(t('brand'))}</b><p>${esc(t('legal'))}</p><p>${esc(t('footerNote'))}</p></footer></main>`;}
function statusBadge(c){return c.status==='done'?`<span class="badge ok">✅ ${c.wordCount} ${t('words')}</span>`:c.status==='failed'||c.status==='empty'?`<span class="badge bad">💔 ${t('statusFailed')}</span>`:`<span class="badge idle">⏳ ${t('statusPending')}</span>`;}
function bookView(){const b=S.book,ch=S.chapters;const done=ch.filter(c=>c.status==='done').length;const pending=ch.filter(c=>c.status==='pending'||c.status==='fetching').map(c=>c.idx);const failed=ch.filter(c=>c.status==='failed'||c.status==='empty').map(c=>c.idx);const pct=ch.length?Math.round(done/ch.length*100):0;const p=S.progress;
const head=`<section class="card book"><div>${b.hasCover?`<img class="cover" src="${API}cover&id=${b.id}" alt="">`:`<div class="cover" style="aspect-ratio:3/4;display:grid;place-items:center;font-size:48px;background:rgba(255,255,255,.7)">🌷</div>`}<span class="chip" style="display:block;text-align:center;margin-top:8px">🖼️ ${t('cover')}</span></div><div style="display:grid;gap:12px;align-content:start"><h1 class="gold" style="font-size:1.7rem">${esc(b.title)}</h1><p class="muted" style="margin:0">✍️ ${esc(b.author||'—')}</p><div><span class="chip">📚 ${ch.length} ${t('chapters')}</span><span class="chip">✅ ${done} ${t('fetchedChapters')}</span>${failed.length?`<span class="chip">💔 ${failed.length}</span>`:''}<a class="chip" href="${esc(b.sourceUrl)}" target="_blank" rel="noreferrer noopener" style="text-decoration:none">🔗 ${t('sourceUrl')}</a></div><div class="progress"><span style="width:${Math.max(pct,3)}%"></span></div><p class="muted small" style="margin:0">${done} ${t('of')} ${ch.length} • ${pct}%</p><div><h3 style="font-size:.95rem">📝 ${t('description')}</h3><p style="white-space:pre-wrap;line-height:1.9;font-size:.92rem;margin:0">${esc(b.description||t('noDescription'))}</p></div><div class="row">${pending.length?`<button class="btn" onclick="LC.resume()" ${S.running?'disabled':''}>${S.running?t('fetchingNow'):'💞 '+t('resume')+' ('+pending.length+')'}</button>`:''}${failed.length?`<button class="soft" onclick="LC.retry()" ${S.running?'disabled':''}>♻️ ${t('retryFailed')}</button>`:''}</div>${S.flash?`<p class="card" style="padding:10px;text-align:center;color:var(--rosed);font-weight:800">${esc(S.flash)}</p>`:''}${p&&S.running?`<div><div class="progress"><span style="width:${Math.round((p.done+p.failed)/Math.max(p.total,1)*100)}%"></span></div><p class="muted small">${t('fetchingChapter')} #${p.current} • ${p.done}/${p.total}${p.failed?' • 💔 '+p.failed:''}</p></div>`:''}</div></section>`;
const tabs=`<nav class="row">${[['reader','👀 '+t('readerTitle')],['weights','⚖️ '+t('weightsTitle')],['export','📦 '+t('exportTitle')]].map(x=>`<button class="${S.tab===x[0]?'btn':'soft'}" onclick="LC.tab('${x[0]}')">${x[1]}</button>`).join('')}</nav>`;
let body='';
if(S.tab==='reader'){const c=S.content;let pane;if(S.loadingContent)pane='<div class="skel"></div>'.repeat(6);else if(!c)pane=`<p class="muted">${t('noContentYet')}</p>${S.active!==null&&!S.running?`<button class="btn" onclick="LC.fetchOne(${S.active})">🎀 ${t('fetchThisChapter')}</button>`:''}`;else if(c.status!=='done')pane=`<p class="note">🥺 ${c.status==='failed'?t('chapterFailed'):t('noContentYet')}${c.error?' ('+esc(c.error)+')':''}</p><button class="btn" onclick="LC.fetchOne(${c.idx})" ${S.running?'disabled':''}>♻️ ${t('fetchThisChapter')}</button>`;else{const blocks=c.blocks&&c.blocks.length?c.blocks:(c.plainText||'').split('\n').map(x=>({type:'p',text:x}));pane=`<article class="reader">${blocks.map(x=>x.type==='img'?`<img loading="lazy" src="${API}image&u=${encodeURIComponent(x.src)}&r=${encodeURIComponent(b.sourceUrl)}" alt="${esc(x.alt||'')}">`:x.type==='h'?`<h3>${esc(x.text)}</h3>`:(x.text&&x.text.trim()?`<p>${esc(x.text)}</p>`:'')).join('')}</article>`;}
body=`<section class="two"><div class="card list"><h3 style="font-size:.9rem;padding:4px 8px">🔖 ${t('chapters')}</h3>${ch.map(c=>`<button class="${S.active===c.idx?'on':''}" onclick="LC.pick(${c.idx})"><b>${c.idx}. ${esc(c.title||t('chapter'))}</b>${statusBadge(c)}</button>`).join('')}</div><div class="card"><div class="row between"><h2 style="margin:0">${c?esc(c.idx+'. '+c.title):t('selectChapter')}</h2>${c&&c.imageCount?`<span class="chip">🖼️ ${c.imageCount} ${t('imagesInChapter')}</span>`:''}</div><p class="muted small">💡 ${t('readerHint')}</p>${pane}</div></section>`;}
else if(S.tab==='weights'){const w=S.weights;const rows=w?w.formats:FORMATS.map(f=>({format:f[0],bytes:0,estimated:true}));const mx=Math.max(1,...rows.map(r=>r.bytes));const sorted=w?[...w.perChapter].sort((a,b2)=>b2.bytes-a.bytes):[];const heavy=sorted[0],light=sorted[sorted.length-1];
body=`<section class="card"><h2>⚖️ ${t('weightsTitle')}</h2><p class="muted small">${t('weightsSubtitle')}</p><div class="grid g6">${[['📚',t('totalChapters'),w?w.totals.chapters:ch.length],['✅',t('fetchedChapters'),w?w.totals.fetched:done],['🔤',t('words'),(w?w.totals.words:0).toLocaleString()],['🖼️',t('images'),w?w.totals.images:0],['⏱️',t('readingTime'),w?w.totals.readingMinutes:0],['💝',t('cover'),fmtBytes(w?w.totals.coverBytes:0)]].map(x=>`<div class="card" style="padding:12px;text-align:center"><span style="font-size:22px">${x[0]}</span><p style="margin:4px 0;font-weight:800;color:var(--plum);font-size:1.1rem">${x[2]}</p><span class="muted small">${x[1]}</span></div>`).join('')}</div><div style="display:grid;gap:8px;margin-top:16px">${rows.map(r=>{const f=FORMATS.find(x=>x[0]===r.format)||['','📦'];return `<div class="row"><b style="width:100px;color:var(--plum);font-size:12px">${f[1]} ${r.format.toUpperCase()}</b><span class="bar"><span style="width:${Math.max(4,Math.round(r.bytes/mx*100))}%"></span></span><b style="width:80px;text-align:end;font-size:12px">${fmtBytes(r.bytes)}</b><span class="muted small" style="width:70px;text-align:end">${r.estimated?'≈ '+t('estimated'):'📐 '+t('measured')}</span></div>`;}).join('')}</div>${heavy&&light?`<p class="muted small">🏋️ ${t('heaviest')}: <b>${heavy.idx}. ${esc(heavy.title)}</b> (${fmtBytes(heavy.bytes)}) • 🪶 ${t('lightest')}: <b>${light.idx}. ${esc(light.title)}</b> (${fmtBytes(light.bytes)})</p>`:''}</section><section class="card" style="max-height:60vh;overflow:auto"><h3 style="font-size:.9rem">🔖 ${t('chapterWeights')}</h3><table><thead><tr><th>#</th><th style="text-align:start">${t('chapters')}</th><th>${t('words')}</th><th>${t('images')}</th><th>${t('size')}</th><th>${t('share')}</th></tr></thead><tbody>${(w?w.perChapter:[]).map(r=>`<tr><td><b>${r.idx}</b></td><td class="t">${esc(r.title)}</td><td>${r.words}</td><td>${r.images}</td><td>${fmtBytes(r.bytes)}</td><td>${r.share}%</td></tr>`).join('')}</tbody></table></section>`;}
else{const w=S.weights;body=`<section class="card"><h2>📦 ${t('exportTitle')}</h2><p class="muted small">${t('exportSubtitle')}</p><div class="grid g4">${FORMATS.map(f=>{const wt=w?w.formats.find(x=>x.format===f[0]):null;const off=done===0;return `<a class="card fmt ${off?'off':''}" href="${API}export&id=${b.id}&format=${f[0]}"><div class="row between"><span style="font-size:26px">${f[1]}</span><span class="badge" style="background:var(--rosed);color:#fff">${f[2]}</span></div><p class="muted small" style="margin:8px 0">${esc(L(f[3]))}</p><b style="color:var(--plum);font-size:.9rem">⬇️ ${t('download')} • ${fmtBytes(wt?wt.bytes:0)}</b></a>`;}).join('')}</div>${w&&w.totals.failed?`<p class="note" style="margin-top:12px">💔 ${t('unavailableNote')}</p>`:''}<p class="muted small">🎀 ${t('poweredBy')} • ${esc(t('legal'))}</p></section><section class="card muted small"><h3 style="font-size:.9rem">🔗 ${t('sourceUrl')}</h3><a href="${esc(b.sourceUrl)}" target="_blank" rel="noreferrer noopener" style="word-break:break-all">${esc(b.sourceUrl)}</a></section>`;}
return `<main class="wrap"><a class="soft small" href="#/" style="width:fit-content">← ${t('back')}</a>${head}${tabs}${body}</main>`;}
function render(){const app=$('#app');const url=$('#url')?$('#url').value:null;app.innerHTML=header()+(S.view==='book'&&S.book?bookView():home());if(url!==null&&$('#url'))$('#url').value=url;}
function renderStatus(){const el=$('#importStatus');if(el)el.innerHTML=importStatus();}
/* ---------- actions ---------- */
async function loadLibrary(){try{const d=await jget('books');S.books=d.books||[];}catch(e){S.books=[];}render();}
async function loadBook(id){try{const d=await jget('book&id='+id);S.book=d.book;S.chapters=d.chapters||[];S.view='book';const first=S.chapters.find(c=>c.status==='done');S.active=first?first.idx:null;S.content=null;render();if(S.active!==null)pick(S.active);loadWeights();}catch(e){location.hash='#/';}}
async function loadWeights(){try{S.weights=await jget('weights&id='+S.book.id);if(S.tab!=='reader')render();}catch(e){}}
async function pick(idx){S.active=idx;S.loadingContent=true;render();try{const d=await jget('chapter&id='+S.book.id+'&idx='+idx);S.content=d.chapter;}catch(e){S.content=null;}S.loadingContent=false;render();}
async function refreshBook(){try{const d=await jget('book&id='+S.book.id);S.book=d.book;S.chapters=d.chapters||[];}catch(e){}}
async function runPending(idxs){if(!idxs.length||S.running)return;S.running=true;S.progress={total:idxs.length,done:0,failed:0,current:idxs[0]};S.flash=t('fetchingNow');render();await runLoop(S.book.id,idxs,(c,p)=>{S.progress=p;if(c&&c.idx){const i=S.chapters.findIndex(x=>x.idx===c.idx);if(i>=0&&c.title!==undefined)S.chapters[i]=Object.assign({},S.chapters[i],c);}if(p.done%4===0)hearts(3);render();});S.running=false;hearts(18);S.flash=t('done');await refreshBook();render();loadWeights();if(S.active!==null)pick(S.active);setTimeout(()=>{S.flash='';render();},2500);}
window.LC={
locale(l){S.locale=l;chrome();render();},
theme(th){S.theme=th;chrome();render();},
async start(){const v=($('#url')?$('#url').value:'').trim();if(!v){S.imp={phase:'error',error:t('errorEmpty'),book:null,chapters:[],progress:null};renderStatus();$('#url').classList.add('pop');return;}S.imp={phase:'meta',error:'',book:null,chapters:[],progress:null};render();$('#url').value=v;hearts(8);try{const r=await jpost('import',{url:v});S.imp.book=r.book;S.imp.chapters=r.chapters||[];hearts(12);const pending=S.imp.chapters.filter(c=>c.status!=='done').map(c=>c.idx);if(!pending.length){S.imp.phase='done';renderStatus();setTimeout(()=>{location.hash='#/book/'+r.book.id;},900);return;}S.imp.phase='chapters';S.imp.progress={total:pending.length,done:0,failed:0,current:pending[0]};renderStatus();await runLoop(r.book.id,pending,(c,p)=>{S.imp.progress=p;if(p.done%3===0)hearts(4);renderStatus();});S.imp.phase='done';renderStatus();hearts(24);setTimeout(()=>{location.hash='#/book/'+r.book.id;},1100);}catch(e){const code=e.code;S.imp.phase='error';S.imp.error=code==='empty'?t('errorEmpty'):code==='invalid'?t('errorInvalid'):code==='truncated'?t('errorTruncated'):(e.message&&e.message!=='generic'?e.message:t('errorGeneric'));render();}},
async del(id){if(!confirm(t('deleteConfirm')))return;try{await jpost('delete&id='+id);}catch(e){}S.books=S.books.filter(b=>b.id!==id);render();},
tab(x){S.tab=x;render();if(x!=='reader')loadWeights();},
pick(i){pick(i);},
resume(){runPending(S.chapters.filter(c=>c.status==='pending'||c.status==='fetching').map(c=>c.idx));},
async retry(){try{const d=await jpost('retry&id='+S.book.id);S.chapters=d.chapters||S.chapters;}catch(e){}runPending(S.chapters.filter(c=>c.status==='pending').map(c=>c.idx));},
fetchOne(i){runPending([i]);}
};
function route(){const h=location.hash||'#/';const m=h.match(/^#\/book\/(\d+)/);if(m){loadBook(parseInt(m[1],10));}else{S.view='home';S.book=null;S.content=null;S.tab='reader';render();loadLibrary();}}
window.addEventListener('hashchange',route);
chrome();
if(BOOT.open&&!location.hash){location.hash='#/book/'+BOOT.open;}else{route();}
})();
</script>
</body>
</html>
HTML;
    return str_replace('__BOOT__', json_encode($boot, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG), $html);
}
